		provider: z.string(),
		modelId: z.string(),
		specificationVersion: z.string().optional(),
		originalConfig: z.union([z.string(), z.record(z.string(), z.any())]).optional(),
		settings: z.record(z.string(), z.any()).optional(),
		providerOptions: z.record(z.string(), z.any()).optional()
